from __future__ import absolute_import
from selenium.webdriver.common.by import By
from selenium.common.exceptions import TimeoutException
from taf.selenium.sbts_fsm3 import pages
from taf.selenium.sbts_fsm3.pages.modals import ReadSensorDataModal


class CentralizedRaeManagementPage(pages.configuration.CentralizedRaeManagementPage):
    def __init__(self, driver, download_checker):
        super(CentralizedRaeManagementPage, self).__init__(driver, download_checker)
        self._view_panel = CentralizedRaeManagementPageViewPanel(driver, download_checker)

    def read_sensor_data(self, timeout=60):
        return self._view_panel.read_sensor_data(timeout)

    def get_1d_weight_factors(self, rae_unit, electrical_tilt, broadcast_beam_width, frequency_band, timeout=60):
        return self._view_panel.get_1d_weight_factors(rae_unit,
                                                      electrical_tilt,
                                                      broadcast_beam_width,
                                                      frequency_band,
                                                      timeout)


class CentralizedRaeManagementPageViewPanel(pages.configuration.CentralizedRaeManagementPageViewPanel):
    WEIGHT_FACTOR_DATA_DOWNLOADED = '2D weight factor data downloaded'
    SAVE_BUTTON = '//button[contains(text(), "Download file")]'
    READ_SENSOR_DATA_BUTTON = '//button[contains(text(), "Read Sensor Data")]'
    READ_SENSOR_DATA_COMPLETED = 'Reading sensor data complete.'
    GET_WEIGHT_FACTORS_BUTTON = ('//*[contains(@class, "rae-weight-factors-table")]'
                                 '//button[contains(text(), "Get Weight Factors")]')

    ELECTRICAL_TILT_DROPDOWN_XPATH = '//*[@*="$ctrl.antenna1DParas.electricalTilt"]//button'
    BROADCAST_BEAM_WIDTH_DROPDOWN_XPATH = '//*[@*="$ctrl.antenna1DParas.broadcastBeamWidth"]//button'
    FREQUENCY_BAND_DROPDOWN_XPATH = '//*[@*="$ctrl.antenna1DParas.frequencies"]//button'
    GET_1D_WEIGHT_FACTORS_BUTTON = ('//*[contains(@class, "rae-one-d-weight-factors")]'
                                    '//button[contains(text(), "Get Weight Factors")]')

    WEIGHT_FACTOR_TD_ELEMENT = '//div[@class="rae-weight-factors-table"]//tbody//tree-table-td//span'
    WEIGHT_FACTOR_KEYS = ['Port', 'Polarity', 'Amplitude', 'Phase']

    RAE_1D_WEIGHT_FACTOR_TITLE = ('//*[contains(@class, "rae-one-d-weight-factors")]'
                                  '//table[contains(@class, "rae-one-d-weight-reasult-table")]//thead//th')
    RAE_1D_WEIGHT_FACTOR_INFO = ('//*[contains(@class, "rae-one-d-weight-factors")]'
                                 '//table[contains(@class, "rae-one-d-weight-reasult-table")]//tbody//tr')

    def __init__(self, driver, download_checker):
        super(CentralizedRaeManagementPageViewPanel, self).__init__(driver, download_checker)

    def read_sensor_data(self, timeout=60):
        self.click_enabled_element((By.XPATH, self.READ_SENSOR_DATA_BUTTON), timeout)
        modal = ReadSensorDataModal(driver=self.driver)
        modal.wait_until_read_sensor_data_modal_appear()
        modal.read()
        self._wait_for_element_by((By.XPATH,
                                   self.EXPECTED_RAE_MANAGE_PROGRESS.format(self.READ_SENSOR_DATA_COMPLETED)), timeout)
        return self.READ_SENSOR_DATA_COMPLETED

    def get_1d_weight_factors(self, rae_unit, electrical_tilt, broadcast_beam_width, frequency_band, timeout=60):
        self._click_rae_unit(rae_unit)
        self.select_element_from_dropdown_list_by_text_and_click(
            electrical_tilt,
            (By.XPATH, self.ELECTRICAL_TILT_DROPDOWN_XPATH),
            (By.XPATH, self.DROP_DOWN_OPTION.format(electrical_tilt))
        )
        self.select_element_from_dropdown_list_by_text_and_click(
            broadcast_beam_width,
            (By.XPATH, self.BROADCAST_BEAM_WIDTH_DROPDOWN_XPATH),
            (By.XPATH, self.DROP_DOWN_OPTION.format(broadcast_beam_width))
        )
        self.select_element_from_dropdown_list_by_text_and_click(
            frequency_band,
            (By.XPATH, self.FREQUENCY_BAND_DROPDOWN_XPATH),
            (By.XPATH, self.DROP_DOWN_OPTION.format(frequency_band))
        )
        self.click_enabled_element((By.XPATH, self.GET_1D_WEIGHT_FACTORS_BUTTON), timeout)
        return self._get_1d_weight_factor(timeout)

    def _get_1d_weight_factor(self, timeout=60):
        progress = '1D weight factor data downloaded'
        try:
            self._wait_for_element_by((By.XPATH,
                                       self.EXPECTED_RAE_MANAGE_PROGRESS.format(progress)),
                                      timeout)
        except TimeoutException:
            progress = self.driver.find_element_by_xpath(self.CURRENT_RAE_MANAGE_PROGRESS).text
            if "Data read from cache" not in progress:
                return [progress, []]

        titles = [elem.text.strip() for elem in self.driver.find_elements_by_xpath(self.RAE_1D_WEIGHT_FACTOR_TITLE)]
        info = []
        for tr_elem in self.driver.find_elements_by_xpath(self.RAE_1D_WEIGHT_FACTOR_INFO):
            tr_info = [elem.text.strip() for elem in tr_elem.find_elements_by_xpath(".//td")]
            info.append(dict(zip(titles, tr_info)))
        return [progress, info]
